scripts.script:
while task.wait() do
local args = {
    [1] = {}
}

local Pack = game:GetService("ReplicatedStorage"):WaitForChild("OpenPack"):InvokeServer(unpack(args))
if Pack == 'rateLimited' then task.wait(3) else
print("Unpacked @"..Pack.Username,'('..Pack.DisplayName..')')
end
end

local args = {
    [1] = "Claim"
}

game:GetService("ReplicatedStorage"):WaitForChild("Packages"):WaitForChild("Knit"):WaitForChild("Services"):WaitForChild("ChestService"):WaitForChild("RE"):WaitForChild("Chest"):FireServer(unpack(args))
